function bindHomeBanner(){const shell=$('#homeBannerShell');if(!shell||shell.dataset.bound==='1')return;shell.dataset.bound='1';shell.addEventListener('click',e=>{const prev=e.target.closest('[data-banner-prev]'),next=e.target.closest('[data-banner-next]'),dot=e.target.closest('[data-home-banner-dot]');if(prev){e.preventDefault();goHomeBanner(HOME_BANNER.index-1,true)}if(next){e.preventDefault();goHomeBanner(HOME_BANNER.index+1,true)}if(dot){e.preventDefault();goHomeBanner(Number(dot.dataset.homeBannerDot),true)}});shell.addEventListener('pointerenter',()=>{HOME_BANNER.paused=true;stopHomeBanner()});shell.addEventListener('pointerleave',()=>{HOME_BANNER.paused=false;startHomeBanner()});shell.addEventListener('touchstart',e=>{HOME_BANNER.touchX=e.touches?.[0]?.clientX||0},{passive:true});shell.addEventListener('touchend',e=>{const dx=(e.changedTouches?.[0]?.clientX||0)-HOME_BANNER.touchX;if(Math.abs(dx)>45)goHomeBanner(HOME_BANNER.index+(dx<0?1:-1),true)},{passive:true});document.addEventListener('visibilitychange',()=>document.hidden?stopHomeBanner():startHomeBanner())}
