function dailyKujiPrize(){const table=[['A賞',1,'大吉','超大吉｜今天手氣滿點','今天的收藏運是最高級，看到真正想要的可以果斷一點。'],['B賞',1,'大吉','大吉｜好運直接命中','今天很適合挑戰平常捨不得下手的收藏。'],['C賞',1,'中吉','中吉｜驚喜正在靠近','逛商城時多看幾眼，可能會遇到超出預期的好東西。'],['D賞',1,'中吉','中吉｜今天很會挑','直覺不錯，第一眼就喜歡的通常很適合你。'],['E賞',6,'吉','吉｜收藏運上升','今天適合找新品，也適合補一直缺的收藏。'],['F賞',8,'吉','吉｜穩定好手氣','慢慢逛會比急著決定更容易找到對的東西。'],['G賞',10,'小吉','小吉｜會遇到小驚喜','今天的小確幸可能藏在不起眼的商品裡。'],['H賞',14,'小吉','小吉｜尋寶日','多翻幾個分類，容易找到平常沒注意到的角色。'],['I賞',18,'末吉','末吉｜先收藏再說','今天看到喜歡的先收藏，之後回來看可能更有感覺。'],['J賞',20,'末吉','末吉｜頑夜陪你尋寶','今天先享受逛店的樂趣，好運可能晚一點出現。']];const pool=[];table.forEach(([grade,count,jp,title,text])=>{for(let i=0;i<count;i++)pool.push({grade,jp,title,text})});let n;if(globalThis.crypto?.getRandomValues){const a=new Uint32Array(1),limit=Math.floor(4294967296/pool.length)*pool.length;let v;do{crypto.getRandomValues(a);v=a[0]}while(v>=limit);n=v%pool.length}else n=Math.floor(Math.random()*pool.length);return Object.assign({poolIndex:n+1,total:80},pool[n])}
function dailyKujiAudio(kind,intensity=1){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ac=window.__wanyeKujiAC||(window.__wanyeKujiAC=new AC());ac.resume();const now=ac.currentTime;if(kind==='tear'){const burst=(delay=0,dur=.055,amp=.11,freq=1450)=>{const len=Math.max(64,Math.floor(ac.sampleRate*dur)),buf=ac.createBuffer(1,len,ac.sampleRate),data=buf.getChannelData(0);let last=0;for(let i=0;i<len;i++){const n=(Math.random()*2-1),crackle=Math.random()>.82?(Math.random()*2-1)*.9:0;last=.72*last+.28*(n+crackle);data[i]=last*(1-i/len)}const src=ac.createBufferSource(),bp=ac.createBiquadFilter(),g=ac.createGain();src.buffer=buf;bp.type='bandpass';bp.frequency.value=freq+Math.random()*700;bp.Q.value=.75;const st=now+delay;g.gain.setValueAtTime(.001,st);g.gain.exponentialRampToValueAtTime(Math.max(.02,amp*intensity),st+.006);g.gain.exponentialRampToValueAtTime(.001,st+dur);src.connect(bp).connect(g).connect(ac.destination);src.start(st)};burst(0,.045,.105,1300);burst(.038,.05,.085,1850);if(intensity>.75)burst(.082,.06,.07,2400)}else if(kind==='peel'){[0,.045,.09,.135].forEach((d,i)=>{const o=ac.createOscillator(),g=ac.createGain();o.type='triangle';o.frequency.setValueAtTime(115-i*8,now+d);o.frequency.exponentialRampToValueAtTime(72,now+d+.07);g.gain.setValueAtTime(.001,now+d);g.gain.exponentialRampToValueAtTime(.035,now+d+.006);g.gain.exponentialRampToValueAtTime(.001,now+d+.075);o.connect(g).connect(ac.destination);o.start(now+d);o.stop(now+d+.08)})}else{[523.25,659.25,783.99,1046.5].forEach((freq,i)=>{const o=ac.createOscillator(),g=ac.createGain();o.type=i===3?'triangle':'sine';o.frequency.value=freq;const st=now+i*.075;g.gain.setValueAtTime(.001,st);g.gain.exponentialRampToValueAtTime(.105,st+.018);g.gain.exponentialRampToValueAtTime(.001,st+.46);o.connect(g).connect(ac.destination);o.start(st);o.stop(st+.48)})}}catch(e){}}
