function armDailyKujiResult(box){if(!box)return null;if(box._dailyPrize)return box._dailyPrize;const p=dailyKujiPrize();box._dailyPrize=p;const g=box.querySelector('[data-daily-grade]'),j=box.querySelector('[data-daily-jp]'),t=box.querySelector('[data-daily-title]'),d=box.querySelector('[data-daily-text]'),serial=box.querySelector('[data-daily-serial]');if(g)g.textContent=p.grade;if(j)j.textContent=p.jp;if(t)t.textContent=p.title;if(d)d.textContent=p.text;if(serial)serial.textContent=String(p.poolIndex).padStart(2,'0')+'/80';box.dataset.prizeLocked='1';return p}
function setDailyTearProgress(box,p,play=true){p=Math.max(0,Math.min(1,p));box.style.setProperty('--tear-progress',(p*100).toFixed(2)+'%');box.dataset.tearProgress=String(p);const result=box.querySelector('[data-daily-result]');if(result){if(p>=.18){result.hidden=false;box.classList.add('result-visible')}else{result.hidden=true;box.classList.remove('result-visible')}}const steps=Number(box.dataset.tearSteps||0),next=Math.floor(p*12);if(play&&next>steps){for(let i=steps;i<next;i++)setTimeout(()=>dailyKujiAudio('tear',.55+.35*(i/12)),(i-steps)*18);box.dataset.tearSteps=String(next);try{if(navigator.vibrate&&next>steps)navigator.vibrate(5)}catch(e){}}}
function initDailyKujiTear(box){const handle=box.querySelector('[data-daily-kuji-tear]'),ticket=box.querySelector('.daily-kuji-ticket');if(!handle||!ticket)return;let dragging=false,startX=0,startP=0;const width=()=>Math.max(180,ticket.getBoundingClientRect().width*.78);const down=e=>{if(box.classList.contains('revealed'))return;armDailyKujiResult(box);dragging=true;startX=e.clientX;startP=Number(box.dataset.tearProgress||0);handle.setPointerCapture?.(e.pointerId);box.classList.add('dragging');dailyKujiAudio('tear',.5);e.preventDefault()};const move=e=>{if(!dragging)return;const p=Math.max(startP,(e.clientX-startX)/width()+startP);setDailyTearProgress(box,p,true);if(p>=.985){dragging=false;box.classList.remove('dragging');revealDailyKuji();try{handle.releasePointerCapture?.(e.pointerId)}catch(_){}}};const up=e=>{if(!dragging)return;dragging=false;box.classList.remove('dragging');const p=Number(box.dataset.tearProgress||0);if(p>.72)revealDailyKuji();else{box.classList.add('snapback');setDailyTearProgress(box,0,false);box.dataset.tearSteps='0';setTimeout(()=>box.classList.remove('snapback'),280)}try{handle.releasePointerCapture?.(e.pointerId)}catch(_){}};handle.addEventListener('pointerdown',down);handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',up);handle.addEventListener('pointercancel',up);handle.addEventListener('click',e=>{if(Number(box.dataset.tearProgress||0)<.08){armDailyKujiResult(box);setDailyTearProgress(box,1,true);setTimeout(revealDailyKuji,180)}e.preventDefault()})}

function revealDailyKuji(){const box=$('#dailyKujiOverlay');if(!box||box.classList.contains('revealed')||box.classList.contains('finishing'))return;const p=armDailyKujiResult(box),day=taipeiDayKey(),result=box.querySelector('[data-daily-result]');if(result)result.hidden=false;box.classList.add('result-visible','finishing');setDailyTearProgress(box,1,true);dailyKujiAudio('peel');setTimeout(()=>{box.classList.remove('finishing','tearing','dragging');box.classList.add('revealed');try{localStorage.setItem('wanye:dailyKujiResult:'+day,JSON.stringify(p))}catch(e){}dailyKujiAudio('win');try{navigator.vibrate?.([18,35,28])}catch(e){}},420)}
