async function loadClosingBootstrap(offset=0){const d=await loadStaticJson('./closing-products-v2851.json?v=2874');const all=Array.isArray(d?.items)?d.items.filter(isClosing):[];const items=all.slice(offset,offset+PAGE_SIZE);const cats=[...new Set(all.map(x=>x.category).filter(Boolean))].sort();const ips=[...new Set(all.map(getIp).filter(Boolean))].sort();return {ok:true,items,total:all.length,nextOffset:offset+items.length,hasMore:offset+items.length<all.length,categories:cats,ips,counts:{all:Number(d?.publicCount||all.length),closing:all.length,new:all.filter(x=>x.isNew).length}}}
