function localProductSort(items,sort){items=items.slice();const created=x=>Date.parse((x.createdAt||'')+'T00:00:00')||0,row=x=>Number(x.rowOrder||0);if(sort==='priceAsc')items.sort((a,b)=>Number(a.price||0)-Number(b.price||0));else if(sort==='priceDesc')items.sort((a,b)=>Number(b.price||0)-Number(a.price||0));else if(sort==='closing')items.sort((a,b)=>(Date.parse(a.closeDate||'')||8640000000000000)-(Date.parse(b.closeDate||'')||8640000000000000));else items.sort((a,b)=>(created(b)-created(a))||(row(b)-row(a)));return items}
function staticShopData(q){q=q||{};const idx=S.shopIndex||buildShopIndex(S.shopStatic?.items||[]),mode=q.mode||'all',pools=[];if(q.category)pools.push(idx.byCat.get(q.category)||[]);if(q.ip)pools.push(idx.byIp.get(q.ip)||[]);if(mode!=='all'&&idx.modes[mode])pools.push(idx.modes[mode]);let base=pools.length?pools.reduce((a,b)=>a.length<=b.length?a:b):idx.all,ids=Array.isArray(q.ids)?new Set(q.ids.map(String)):null,needle=String(q.q||'').trim().toLowerCase();let list=base.filter(p=>{if(ids&&!ids.has(productId(p)))return false;if(q.category&&p.category!==q.category)return false;if(q.ip&&getIp(p)!==q.ip)return false;if(mode==='new'&&!p.isNew)return false;if(mode==='closing'&&!isClosing(p))return false;if(mode==='direct'&&!/現貨|直購/.test(String(p.type||'')))return false;if(mode==='long'&&!p.isLongTerm)return false;if(needle&&!(p._hay||'').includes(needle))return false;return true});list=localProductSort(list,q.sort||'new');const off=Math.max(0,Number(q.offset||0)),page=list.slice(off,off+PAGE_SIZE);return{ok:true,items:page,total:list.length,nextOffset:off+page.length,hasMore:off+page.length<list.length,categories:idx.categories,ips:idx.ips,counts:idx.counts}}
